// ======================================================
// SENSOR KEY
// ======================================================
let sensorKey = `${msg.plc_code}/${msg.sensor_code}`;
let now = Date.now();

// ======================================================
// AMBIL INTERVAL
// ======================================================
let intervalMap = flow.get("intervalMap") || {};
let lastInsertMap = flow.get("lastInsertMap") || {};

// fallback default 30 menit
//let intervalMin = intervalMap[sensorKey] || 30;
let intervalMin = Number(msg.interval) || 30;
let intervalMs = intervalMin * 60 * 1000;
let intervalSec = intervalMin * 60;
// let lastInsert = lastInsertMap[sensorKey] || 0;

// ======================================================
// CEK INTERVAL (BERDASARKAN CLOCK-ALIGNED)
// ======================================================
let currentBucketId = Math.floor(now / intervalMs);
let lastBucketId = lastInsertMap[sensorKey] || 0;

if (currentBucketId === lastBucketId) {
    return null; // Masih di rentang waktu yang sama, abaikan pesan
}

// ======================================================
// UPDATE LAST INSERT
// ======================================================
lastInsertMap[sensorKey] = currentBucketId;
flow.set("lastInsertMap", lastInsertMap);

// ======================================================
// BUILD SQL HISTORY
// ======================================================
msg.topic = `
INSERT INTO sensor_history
(
    plc_code,
    sensor_code,
    value,
    timestamp
)
SELECT
    plc_code,
    sensor_code,
    SUBSTRING_INDEX(GROUP_CONCAT(value ORDER BY timestamp DESC), ',', 1) AS value,
    FROM_UNIXTIME(
        CEILING(
            UNIX_TIMESTAMP(timestamp) / ${intervalSec}
        ) * ${intervalSec}
    ) AS time_bucket
FROM sensor_realtime
WHERE sensor_code = '${msg.sensor_code}'
AND plc_code = '${msg.plc_code}'
AND timestamp >= DATE_SUB(NOW(), INTERVAL 7 DAY)

AND timestamp <= FROM_UNIXTIME(FLOOR(UNIX_TIMESTAMP(NOW()) / ${intervalSec}) * ${intervalSec})

GROUP BY
    plc_code,
    sensor_code,
    time_bucket
ON DUPLICATE KEY UPDATE
    value = VALUES(value);
`;

return msg;

let lastSeenSensor = flow.get("lastSeenSensor") || {};
let statusSensor = flow.get("statusSensor") || {};

let timeoutMs = 65000; // interval PLC = 1 menit → timeout 65 detik
let now = Date.now();

let queries = [];

for (let key in lastSeenSensor) {
    let last = lastSeenSensor[key];

    if (now - last > timeoutMs) {

        if (statusSensor[key] !== "offline") {
            statusSensor[key] = "offline";
            flow.set("statusSensor", statusSensor);

            let [plc_code, sensor_code] = key.split("/");

            queries.push(`
                INSERT INTO sensor_log 
                (plc_code, sensor_code, status, event_time)
                VALUES ('${plc_code}', '${sensor_code}', '0', NOW());
            `);
        }
    }
}

if (queries.length > 0) {
    return { topic: queries.join("\n") };
}

return null;

// Contoh: msg.topic = "data/07/RT0201/7020449001020126076"
// Ambil sensor code dari topik MQTT
const topicParts = msg.topic.split("/");
const sensorCode = topicParts[2]; // "RT0201"

// Ambil data dari payload
const data = msg.payload;

// Pastikan payload valid
if (!data || !sensorCode) return null;

// Buat pesan bersih untuk WebSocket
msg.payload = {
