        valueConverted = parseFloat(rawValue) / 1000;
        break;
    case "02":
    case "03":
    case "04":
        valueConverted = parseFloat(rawValue) / 10;
        break;
    default:
        valueConverted = parseFloat(rawValue);
}

// ======================================================
